-- The 31 facilities in the Inventory of Evacuation Centers (Santa Maria,
-- Bulacan): 1 official (Permanent) evacuation center and 30 temporary sites.
-- Needs 20261126090000_evacuation_center_details.sql first.
--
-- Names, barangays, addresses, phone numbers and Permanent/Temporary status
-- come from the inventory. Nothing else is invented:
-- * Capacity: no facility has an official figure in the inventory. Covered
--   courts get the MDRRMO's estimate (100–150 people), marked as an estimate.
--   Schools, the chapel, the barangay hall and the municipal center are left
--   unverified (no number) until someone records them.
-- * Map pins: only where map data (OpenStreetMap) has the facility itself,
--   identified by name and address or by DepEd school ID. Each pin is marked
--   unconfirmed until someone checks it on site. Where map data only offers a
--   possible spot, it is kept as a suggestion for admins, not shown on the map.
-- * verification_notes say what still needs checking for each one.
--
-- Running it again adds nothing twice: a facility already listed (same name
-- and barangay) is skipped.

insert into public.evacuation_centers (name, location, barangay, classification, facility_type, contact_numbers, capacity, capacity_max, capacity_status, capacity_source, latitude, longitude, location_status, location_source, suggested_latitude, suggested_longitude, source, remarks, verification_notes, occupants, is_open)
select v.*, 0, true
from (values
  ('Municipal Evacuation Center', 'New Bypass Road, San Gabriel, Santa Maria, Bulacan', 'San Gabriel', 'official', 'evacuation_center', '0923-022-6973', null, null, 'unverified', null, null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 1)', 'Run by the Municipality of Santa Maria (listed under LGU–Municipality of Santa Maria, Bulacan). Status in the inventory: Permanent.', 'Location: the building is not in map data; only “Bypass Road Extension” in San Gabriel is. Pin it on site. Capacity: no official figure in the inventory; record the registered capacity.'),
  ('Sta. Maria National High School', 'Sitio Bunducan, Bagbaguin, Santa Maria, Bulacan', 'Bagbaguin', 'temporary', 'school', '09610741391 / 09317259296', null, null, 'unverified', null, 14.813396, 120.951467, 'unconfirmed', 'OpenStreetMap way 164578150 (“Santa Maria Agro-Industrial High School”): the school’s former name (renamed by Republic Act 10440), on Bunducan Street, Bagbaguin; DepEd school ID 300777', null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 2)', 'Formerly Sta. Maria Agro-Industrial High School (renamed by Republic Act 10440).', 'Capacity: no figure for schools in the MDRRMO guidance; record how many people the school can shelter.'),
  ('Barangay Covered Court', 'Luwasan, Balasing, Santa Maria, Bulacan', 'Balasing', 'temporary', 'covered_court', null, 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, 14.849629, 120.999241, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 3)', null, 'Suggested spot: the only covered court in map data for Balasing (OpenStreetMap way 915666184, unnamed), about 300 m west of Balasing Elementary School. “Luwasan” is not in map data, so it is not confirmed that this court is the one in Luwasan.'),
  ('Buenavista Covered Court', 'Sitio Libis, Buenavista, Santa Maria, Bulacan', 'Buenavista', 'temporary', 'covered_court', '09175160085 / 09999984207', 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 4)', null, 'Location: no covered court for Buenavista in map data. Buenavista Barangay Hall (14.79834, 120.98787) and Buenavista Libis Road are nearby landmarks. Pin it on site.'),
  ('Bulac Covered Court', 'Splashville Subd., Sitio Centro, Bulac, Santa Maria, Bulacan', 'Bulac', 'temporary', 'covered_court', null, 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 5)', null, 'Location: Splashville Subdivision is not in map data. Two covered courts are mapped in Bulac (OpenStreetMap ways 1163652968 at 14.83840, 121.01976 and 1163650352 at 14.83682, 121.02323, the second inside Miguel M. Cruz Memorial School); neither can be tied to Splashville. Pin it on site.'),
  ('Covered Court', 'Purok Centro, Camangyanan, Santa Maria, Bulacan', 'Camangyanan', 'temporary', 'covered_court', null, 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 6)', null, 'Location: no covered court for Camangyanan in map data. Pin it on site.'),
  ('Catmon Multi-Purpose Covered Court (Central)', 'Binayuyo St., Sitio Central, Catmon, Santa Maria, Bulacan', 'Catmon', 'temporary', 'covered_court', '0998-858-9659', 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, 14.829043, 121.002047, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 7)', null, 'Suggested spot: the covered court in central Catmon in map data (OpenStreetMap way 810633066, unnamed), beside Jose Juan Serapio Elementary School and near Holy Family Church. Binayuyo St. is not in map data, so it is not confirmed.'),
  ('Multi-Purpose Covered Court', 'Las Palmas Subd., Caypombo, Santa Maria, Bulacan', 'Caypombo', 'temporary', 'covered_court', null, 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 8)', null, 'Location: two possible courts in map data: a covered court next to Caypombo Barangay Hall (OpenStreetMap way 817961279, 14.85121, 120.97802) and an open court inside Las Palmas Subdivision (way 817961278, 14.85065, 120.97511). Check which one is the listed court and pin it.'),
  ('Caysio Covered Gym', 'Plana Subd., Caysio, Santa Maria, Bulacan', 'Caysio', 'temporary', 'covered_court', '0977-353-6366', 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, 14.845865, 120.968571, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 9)', 'A covered gym; capacity is estimated as for a covered court.', 'Suggested spot: the only covered court in map data for Caysio (OpenStreetMap way 1426691626, unnamed), beside Caysio Elementary School in Plana Subdivision. It may be the school’s court rather than the barangay gym; confirm on site.'),
  ('St. Mary Village Elementary School', 'Northville 5A, Caysio, Santa Maria, Bulacan', 'Caysio', 'temporary', 'school', '0977-353-6366', null, null, 'unverified', null, 14.850535, 120.965105, 'unconfirmed', 'OpenStreetMap way 655866384 (“Northville 5A Elementary School”): same DepEd school ID (158535) as St. Mary Village Elementary School, Northville 5A, Caysio', null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 10)', 'Listed in the inventory as “St, Marys Vill Elem. School”. DepEd name and school ID 158535.', 'Capacity: no figure for schools in the MDRRMO guidance; record how many people the school can shelter.'),
  ('Barangay Guyong Multi-Purpose Covered Court', 'Centro, Guyong Complex, Guyong, Santa Maria, Bulacan', 'Guyong', 'temporary', 'covered_court', '0961-904-7908', 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 11)', null, 'Location: the court is not in map data. Guyong Barangay Hall (14.83616, 120.97636) is mapped and may be part of the Guyong Complex. Pin the court on site.'),
  ('Covered Court', 'Sitio Gitna, Lalakhan, Santa Maria, Bulacan', 'Lalakhan', 'temporary', 'covered_court', null, 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 12)', null, 'Location: no covered court for Lalakhan in map data (Lalakhan Elementary School is on Gitna Street). Pin it on site.'),
  ('Covered Court', 'Beside the new barangay hall, Mag-asawang Sapa, Santa Maria, Bulacan', 'Mag-asawang Sapa', 'temporary', 'covered_court', '0936-136-7863', 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, 14.876018, 120.979281, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 13)', null, 'Suggested spot: “M. Sapa Basketball Court” in map data (OpenStreetMap way 1232812334). The barangay hall in map data is 125 m away, so it may be the old hall; confirm the court is the one beside the new barangay hall.'),
