  ('Ibayong Tabon Covered Court', 'Ibayong Tabon, Parada, Santa Maria, Bulacan', 'Parada', 'temporary', 'covered_court', '09311813114 / 09311813115', 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, 14.807108, 120.987165, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 17)', null, 'Suggested spot: the covered court of “Parada Multipurpose Gym Park” in map data (OpenStreetMap way 1204977946), in Ibayong Tabon near Ibayong Tabon Road. Its map name differs, so confirm it is the Ibayong Tabon Covered Court.'),
  ('Caybanban Covered Court', 'Caybanban, Parada, Santa Maria, Bulacan', 'Parada', 'temporary', 'covered_court', '09311813114 / 09311813115', 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 18)', null, 'Location: the Caybanban road is in map data, but no court near it. Pin it on site.'),
  ('Multi-Purpose Covered Court', '21st Centuryville, Poblacion, Santa Maria, Bulacan', 'Poblacion', 'temporary', 'covered_court', null, 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 19)', null, 'Location: 21st Centuryville is not in map data. Pin the court on site.'),
  ('Covered Court', 'Cityland, Pulong Buhangin, Santa Maria, Bulacan', 'Pulong Buhangin', 'temporary', 'covered_court', null, 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, 14.871404, 121.001516, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 20)', null, 'Suggested spot: “Pulong Buhangin Court” in map data (OpenStreetMap way 817961269), beside Pulong Buhangin Barangay Hall and near the City Land Subdivision stops. Confirm it is the listed Cityland court and not one inside the subdivision.'),
  ('Multi-Purpose Covered Court', 'New Site St., San Gabriel, Santa Maria, Bulacan', 'San Gabriel', 'temporary', 'covered_court', null, 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 21)', null, 'Location: New Site St. is not in map data. Pin the court on site.'),
  ('Covered Court', 'Gulod, San Jose Patag, Santa Maria, Bulacan', 'San Jose Patag', 'temporary', 'covered_court', null, 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 22)', null, 'Location: no covered court in Gulod in map data. Pin it on site.'),
  ('Saint Joseph Elementary School', 'Centro, San Jose Patag, Santa Maria, Bulacan', 'San Jose Patag', 'temporary', 'school', null, null, null, 'unverified', null, null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 23)', null, 'Location: no school by this name in map data or DepEd listings. It may be San Jose Patag Elementary School (Sitio Centro; DepEd ID 105162; 14.82461, 120.98002) or the former basic-education department of St. Joseph College of Bulacan (14.82665, 120.98054). Confirm which, then pin it.'),
  ('Hulo Covered Court', 'Sitio Hulo, San Vicente, Santa Maria, Bulacan', 'San Vicente', 'temporary', 'covered_court', '0968-856-1441', 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 24)', null, 'Location: Sitio Hulo of San Vicente is not in map data, and several courts are mapped in San Vicente. Pin it on site.'),
  ('Covered Court', '119 Silangan, Santa Maria, Bulacan', 'Silangan', 'temporary', 'covered_court', null, 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', null, null, 'unknown', null, null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 25)', null, 'Location: no covered court for Silangan in map data. Pin it on site.'),
  ('Sta. Clara Covered Court', 'Almasiga St., Sta. Clara, Santa Maria, Bulacan', 'Santa Clara', 'temporary', 'covered_court', '09177990664 / 09915227454', 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', 14.828886, 120.954876, 'unconfirmed', 'OpenStreetMap way 1333387063 (“Santa Clara Covered Court”): same name, a covered court in Santa Clara', null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 26)', null, 'Map data puts this court on Tindalo Street; the inventory says Almasiga St. (not in map data). Check the pin on site.'),
  ('Sta. Cruz Elementary School', 'Along Provincial Road, Sta. Cruz, Santa Maria, Bulacan', 'Santa Cruz', 'temporary', 'school', null, null, null, 'unverified', null, 14.842104, 120.956188, 'unconfirmed', 'OpenStreetMap way 192368909 (“Santa Cruz Elementary School”): same name, on Provincial Road; DepEd school ID 105167', null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 27)', null, 'Capacity: no figure for schools in the MDRRMO guidance; record how many people the school can shelter.'),
  ('Sta. Cruz Proper Chapel', 'Along Provincial Road, Sta. Cruz, Santa Maria, Bulacan', 'Santa Cruz', 'temporary', 'chapel', null, null, null, 'unverified', null, 14.835945, 120.955162, 'unconfirmed', 'OpenStreetMap way 1334920970 (“Sta. Cruz Proper Sub-Parish”): the Catholic church of Sta. Cruz Proper on the Santa Maria–Pandi (provincial) road', null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 28)', 'Chapel size not recorded. MDRRMO guidance: about 100–150 people for a larger chapel, 50–100 for a smaller one.', 'Capacity: decide whether it is a larger or smaller chapel and set the estimate. Location: map data names it the Sta. Cruz Proper Sub-Parish; confirm it is the listed chapel.'),
  ('Sta. Cruz High School', 'Sitio Bukid, Sta. Cruz, Santa Maria, Bulacan', 'Santa Cruz', 'temporary', 'school', null, null, null, 'unverified', null, 14.838201, 120.959844, 'unconfirmed', 'OpenStreetMap way 915684372 (“Santa Cruz High School – Annex”): the high school at Santa Cruz Bukid (Sitio Bukid); DepEd school ID 306726', null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 29)', 'Listed in the inventory as “Sta. Cruz Highschool”.', 'Map data calls the school at Sitio Bukid “Santa Cruz High School – Annex”; confirm it is the listed school. Capacity: no figure for schools in the MDRRMO guidance; record it.'),
  ('Tabing Bakod Elementary School Covered Court', 'P.N Ramon Ave., Sto. Tomas, Santa Maria, Bulacan', 'Santo Tomas', 'temporary', 'covered_court', null, 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', 14.801272, 120.954647, 'unconfirmed', 'OpenStreetMap way 243705013 (“Tabing Bakod Elementary School”): the school on Pablo N. Ramos Avenue; DepEd school ID 105169. The pin is on the school grounds', null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 30)', 'Sto. Tomas was formerly called Tabing Bakod. Map data names the road Pablo N. Ramos Avenue.', 'The court inside the school is not mapped separately; move the pin onto the court on site.'),
  ('Covered Court', 'Mustasa St., Tumana, Santa Maria, Bulacan', 'Tumana', 'temporary', 'covered_court', null, 100, 150, 'estimated', 'MDRRMO guidance: covered courts hold about 100–150 people', 14.814666, 120.976406, 'unconfirmed', 'OpenStreetMap way 978360481 (“Tumana Covered Court”): same court, on Mustasa Street, next to Tumana Barangay Hall', null, null, 'Inventory of Evacuation Centers, Santa Maria, Bulacan (row 31)', null, 'Check the pin on site.')
) as v (name, location, barangay, classification, facility_type, contact_numbers, capacity, capacity_max, capacity_status, capacity_source, latitude, longitude, location_status, location_source, suggested_latitude, suggested_longitude, source, remarks, verification_notes)
where not exists (
  select 1 from public.evacuation_centers existing
  where regexp_replace(lower(existing.name), '[^a-z0-9]+', '', 'g') = regexp_replace(lower(v.name), '[^a-z0-9]+', '', 'g')
    and coalesce(existing.barangay, '') = coalesce(v.barangay, '')
);
